def render(slug, title, heading, description, sections, hub=False):
    url=BASE+'/'+slug
    schema={'@context':'https://schema.org','@graph':[
      {'@type':'CollectionPage' if hub else 'Article','headline':heading,'description':description,'url':url,'mainEntityOfPage':url,'publisher':{'@type':'Organization','name':'GG Mouse Pro 3','url':BASE}},
      {'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Home','item':BASE+'/'},{'@type':'ListItem','position':2,'name':'Guides','item':BASE+'/guides'}]+([] if hub else [{'@type':'ListItem','position':3,'name':heading,'item':url}])}]}
    content=''.join(f'<section id="section-{i}"><h2>{escape(h)}</h2>{body}</section>' for i,(h,body) in enumerate(sections))
    toc=''.join(f'<a href="#section-{i}">{escape(h)}</a>' for i,(h,_) in enumerate(sections))
    page=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{escape(title)}</title><meta name="description" content="{escape(description,quote=True)}"><link rel="canonical" href="{url}">
<meta property="og:type" content="{'website' if hub else 'article'}"><meta property="og:title" content="{escape(title,quote=True)}"><meta property="og:description" content="{escape(description,quote=True)}"><meta property="og:url" content="{url}"><meta name="twitter:card" content="summary"><meta name="twitter:title" content="{escape(title,quote=True)}"><meta name="twitter:description" content="{escape(description,quote=True)}"><meta name="theme-color" content="#2563eb">
<link rel="stylesheet" href="/css/guides.css"><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script></head>
<body><a class="skip" href="#main">Skip to content</a><header class="site-header"><a class="brand" href="/">GG Mouse Pro 3</a><nav aria-label="Main navigation"><a href="/guides">Guides</a><a href="/activation">Activation</a><a href="/faq">FAQ</a><a href="/download">Download</a></nav></header>
<main id="main"><nav aria-label="Breadcrumb"><a href="/">Home</a> / <a href="/guides">Guides</a>{'' if hub else ' / '+escape(heading)}</nav><div class="hero"><span class="eyebrow">GG MOUSE PRO 3 · SETUP &amp; GUIDES</span><h1>{escape(heading)}</h1><p class="intro">{escape(description)}</p><a class="button" href="/download">Download &amp; set up</a><a href="/contact">Get support</a></div>
<div class="layout"><article>{content}<aside class="callout"><h2>Continue your setup</h2><p><a href="/guides">Browse all guides</a> or <a href="/activation">choose an activation method</a>.</p><a class="button" href="/download">Get GG Mouse Pro 3</a></aside></article><aside class="contents" aria-label="On this page"><strong>On this page</strong>{toc}</aside></div></main>
<footer><nav aria-label="Footer"><a href="/download">Download</a><a href="/contact">Support</a><a href="/privacy-policy">Privacy</a><a href="/terms">Terms</a></nav><p>GG Mouse Pro 3 · Android keyboard and mouse guides</p></footer></body></html>'''
    (ROOT/(slug+'.html')).write_text(page,encoding='utf-8')

for slug, data in PAGES.items(): render(slug,*data)
cards=''.join(f'<div class="card"><h3><a href="/{slug}">{escape(data[1])}</a></h3><p>{escape(data[2])}</p></div>' for slug,data in PAGES.items())
